    df['timestamp'] = pd.to_datetime(df['timestamp'])
    df['week'] = df['timestamp'].dt.weekofyear
    counts = df.groupby('week')['defective'].value_counts(normalize=True).unstack(fill_value=0)
    return counts[1] if 1 in counts.columns else pd.Series(0, index=counts.index)

